{
  "cards": [
    {
      "id": "rag-definition",
      "type": "definition",
      "title": "Retrieval-augmented generation (RAG)",
      "definition": {
        "text": "Retrieval-augmented generation is a pattern that attaches a second, external store to a language model and reads from that store at inference time, conditioning generation on the query together with the retrieved passages.",
        "mode": "summarized",
        "evidenceIds": ["E1", "E5"]
      },
      "keyPoints": [
        {
          "text": "A language model's weights are an awkward knowledge base: they cannot be updated without retraining, cannot cite where a claim came from, and fail silently.",
          "mode": "summarized",
          "evidenceIds": ["E1"]
        },
        {
          "text": "The original RAG pipeline encodes the query, retrieves passages from a dense index, and conditions generation on the query together with the retrieved passages.",
          "mode": "summarized",
          "evidenceIds": ["E5"]
        }
      ]
    }
  ],
  "incomplete": false
}

