      "id": "sparse-vs-dense-retrieval",
      "type": "comparison",
      "title": "Sparse retrieval vs. dense retrieval",
      "entities": ["Sparse retrieval", "Dense retrieval"],
      "rows": [
        {
          "dimension": "Representation",
          "values": [
            {
              "text": "a vector over the vocabulary, almost all of whose entries are zero",
              "mode": "extractive",
              "evidenceIds": ["E1"]
            },
            {
              "text": "queries and passages as vectors in a learned space",
              "mode": "extractive",
              "evidenceIds": ["E5"]
            }
          ]
        },
        {
          "dimension": "Matching method",
          "values": [
            {
              "text": "lookup in an inverted index rather than a distance computation",
              "mode": "extractive",
              "evidenceIds": ["E1"]
            },
            {
              "text": "retrieves by proximity",
              "mode": "extractive",
              "evidenceIds": ["E5"]
            }
          ]
        },
        {
          "dimension": "Core retrieval question",
          "values": [
            {
              "text": "which documents contain these words",
              "mode": "extractive",
              "evidenceIds": ["E5"]
